 // Real existing early handler for isolated reruns; no ML call.
 async Task<Guid> SavedRerun(string proposal,Guid creator){
  var investigation=Guid.NewGuid();await using var seed=new GovernanceIntelligenceDbContext(Options(connection));
  var findings=Enum.GetNames<StateLandGovernance.GovernanceIntelligence.Domain.Enums.EarlyGovernanceIndicatorType>().Select(n=>new OfficerFinding(n,"NotYetVerified","")).ToArray();
  seed.Set<OfficerInvestigationEntity>().Add(new(){Id=investigation,CreatorActorId=creator,SubmissionKey=Guid.NewGuid(),ProposalId=proposal,SourceVersion="isolated/1",InputSha256=new string('b',64),FindingsJson=JsonSerializer.Serialize(findings,new JsonSerializerOptions(JsonSerializerDefaults.Web)),CreatedAtUtc=DateTimeOffset.UtcNow});await seed.SaveChangesAsync();
