  var configuration=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"GovernanceIntelligence:KiwulaWorkspace:WritesEnabled","true"}}).Build();
  var flows=new OfficerFlowStore(seed,configuration,TimeProvider.System,null!,null!,earlyStore,earlyHandler,null!);
  var rerun=await flows.EarlyAsync(creator,new(investigation,Guid.NewGuid()),default);
  Check(rerun.State=="Saved"&&rerun.EarlyAssessmentId!=null,"Existing Early Governance handler genuinely evaluates and persists independent isolated rerun");return rerun.Id;
